Yes. Here is a tiny playable starter game. Copy this into a file called `cat-fish-game.html`, then open it in a web browser.

```html
<!DOCTYPE html>
<html>
<head>
  <title>Cat Catches Fish</title>
  <style>
    body {
      margin: 0;
      background: skyblue;
      text-align: center;
      font-family: Arial, sans-serif;
    }

    canvas {
      background: linear-gradient(skyblue, lightblue);
      display: block;
      margin: 20px auto;
      border: 4px solid white;
    }
  </style>
</head>
<body>
  <h1>Cat Catches Fish</h1>
  <p>Use the left and right arrow keys!</p>
  <canvas id="game" width="500" height="400"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    let cat = {
      x: 220,
      y: 340,
      width: 60,
      height: 40,
      speed: 6
    };

    let fish = {
      x: Math.random() * 460,
      y: 0,
      width: 35,
      height: 25,
      speed: 3
    };

    let score = 0;
    let leftPressed = false;
    let rightPressed = false;

    document.addEventListener("keydown", function(event) {
      if (event.key === "ArrowLeft") {
        leftPressed = true;
      }
      if (event.key === "ArrowRight") {
        rightPressed = true;
      }
    });

    document.addEventListener("keyup", function(event) {
      if (event.key === "ArrowLeft") {
        leftPressed = false;
      }
      if (event.key === "ArrowRight") {
        rightPressed = false;
      }
    });

    function drawCat() {
      ctx.font = "40px Arial";
      ctx.fillText("🐱", cat.x, cat.y + 35);
    }

    function drawFish() {
      ctx.font = "30px Arial";
      ctx.fillText("🐟", fish.x, fish.y + 25);
    }

    function drawScore() {
      ctx.fillStyle = "black";
      ctx.font = "22px Arial";
      ctx.fillText("Score: " + score, 20, 30);
    }

    function moveCat() {
      if (leftPressed && cat.x > 0) {
        cat.x -= cat.speed;
      }

      if (rightPressed && cat.x < canvas.width - cat.width) {
        cat.x += cat.speed;
      }
    }

    function moveFish() {
      fish.y += fish.speed;

      if (fish.y > canvas.height) {
        resetFish();
      }
    }

    function resetFish() {
      fish.x = Math.random() * (canvas.width - fish.width);
      fish.y = 0;
    }

    function checkCatch() {
      if (
        fish.x < cat.x + cat.width &&
        fish.x + fish.width > cat.x &&
        fish.y < cat.y + cat.height &&
        fish.y + fish.height > cat.y
      ) {
        score += 1;
        fish.speed += 0.2;
        resetFish();
      }
    }

    function gameLoop() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      moveCat();
      moveFish();
      checkCatch();

      drawScore();
      drawCat();
      drawFish();

      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
</html>
```

