Let’s make it harder by using a “fish list” instead of just one fish.

Find this part:

```js
let fish = {
  x: Math.random() * 460,
  y: 0,
  width: 35,
  height: 25,
  speed: 3
};
```

Replace it with this:

```js
let fishes = [];

for (let i = 0; i < 5; i++) {
  fishes.push({
    x: Math.random() * 460,
    y: Math.random() * -400,
    width: 35,
    height: 25,
    speed: 2 + Math.random() * 3
  });
}
```

Now find this whole function:

```js
function drawFish() {
  ctx.font = "30px Arial";
  ctx.fillText("🐟", fish.x, fish.y + 25);
}
```

Replace it with:

```js
function drawFish() {
  ctx.font = "30px Arial";

  for (let fish of fishes) {
    ctx.fillText("🐟", fish.x, fish.y + 25);
  }
}
```

Find this:

```js
function moveFish() {
  fish.y += fish.speed;

  if (fish.y > canvas.height) {
    resetFish();
  }
}
```

Replace it with:

```js
function moveFish() {
  for (let fish of fishes) {
    fish.y += fish.speed;

    if (fish.y > canvas.height) {
      resetOneFish(fish);
    }
  }
}
```

Find this:

```js
function resetFish() {
  fish.x = Math.random() * (canvas.width - fish.width);
  fish.y = 0;
}
```

Replace it with:

```js
function resetOneFish(fish) {
  fish.x = Math.random() * (canvas.width - fish.width);
  fish.y = Math.random() * -200;
  fish.speed = 2 + Math.random() * 3;
}
```

