I can’t make a live link from here, but I can give you a tiny game you can play on your computer right now.

Ask a grown-up to help with these steps:

1. Open Notepad, TextEdit, or any code editor.
2. Copy all the code below.
3. Save it as `cat-fish-game.html`
4. Double-click the file to play.

```html
<!DOCTYPE html>
<html>
<head>
  <title>Cat Fish Catch</title>
  <style>
    body {
      margin: 0;
      background: skyblue;
      font-family: Arial, sans-serif;
      text-align: center;
      overflow: hidden;
    }

    h1 {
      margin: 10px;
    }

    #game {
      width: 600px;
      height: 400px;
      background: linear-gradient(skyblue, lightblue);
      border: 4px solid #333;
      margin: auto;
      position: relative;
      overflow: hidden;
    }

    #cat {
      position: absolute;
      bottom: 10px;
      left: 270px;
      font-size: 50px;
    }

    #fish {
      position: absolute;
      top: 0;
      left: 100px;
      font-size: 35px;
    }

    #score {
      font-size: 24px;
      margin: 10px;
    }
  </style>
</head>
<body>

  <h1>Cat Fish Catch</h1>
  <div id="score">Score: 0</div>

  <div id="game">
    <div id="fish">🐟</div>
    <div id="cat">🐱</div>
  </div>

  <p>Use the left and right arrow keys!</p>

  <script>
    const cat = document.getElementById("cat");
    const fish = document.getElementById("fish");
    const scoreText = document.getElementById("score");

    let catX = 270;
    let fishX = Math.random() * 560;
    let fishY = 0;
    let score = 0;

    function meow() {
      const sound = new Audio(
        "https://actions.google.com/sounds/v1/animals/cat_meow.ogg"
      );
      sound.play();
    }

    document.addEventListener("keydown", function(event) {
      if (event.key === "ArrowLeft") {
        catX -= 20;
      }

      if (event.key === "ArrowRight") {
        catX += 20;
      }

      if (catX < 0) {
        catX = 0;
      }

      if (catX > 550) {
        catX = 550;
      }

      cat.style.left = catX + "px";
    });

    function gameLoop() {
      fishY += 4;

      fish.style.top = fishY + "px";
      fish.style.left = fishX + "px";

      const catLeft = catX;
      const catRight = catX + 50;
      const fishLeft = fishX;
      const fishRight = fishX + 35;

      const fishIsLow = fishY > 320;
      const fishTouchesCat = fishRight > catLeft && fishLeft < catRight;

      if (fishIsLow && fishTouchesCat) {
        score++;
        scoreText.textContent = "Score: " + score;
        meow();
        resetFish();
      }

      if (fishY > 400) {
        resetFish();
      }

      requestAnimationFrame(gameLoop);
    }

    function resetFish() {
      fishY = 0;
      fishX = Math.random() * 560;
    }

    gameLoop();
  </script>

</body>
</html>
```

