      position: relative;
      overflow: hidden;
    }

    #cat {
      position: absolute;
      bottom: 10px;
      left: 270px;
      font-size: 50px;
    }

    #fish {
      position: absolute;
      top: 0;
      left: 100px;
      font-size: 35px;
    }

    #dog {
      position: absolute;
      top: -60px;
      left: 300px;
      font-size: 45px;
    }

    #score {
      font-size: 24px;
      margin: 10px;
    }

    #message {
      font-size: 36px;
      font-weight: bold;
      color: red;
      margin: 10px;
      height: 45px;
    }

    #restartButton {
      font-size: 20px;
      padding: 10px 20px;
      display: none;
      cursor: pointer;
    }
  </style>
</head>
<body>

  <h1>Cat Fish Catch</h1>
  <div id="score">Score: 0</div>
  <div id="message"></div>

  <div id="game">
    <div id="fish">🐟</div>
    <div id="dog">🐶</div>
    <div id="cat">🐱</div>
  </div>

  <p>Use the left and right arrow keys!</p>
  <p>Catch fish. Avoid dogs!</p>

  <button id="restartButton" onclick="restartGame()">Play Again</button>

  <script>
    const cat = document.getElementById("cat");
    const fish = document.getElementById("fish");
    const dog = document.getElementById("dog");
    const scoreText = document.getElementById("score");
    const message = document.getElementById("message");
    const restartButton = document.getElementById("restartButton");

    let catX = 270;

    let fishX = Math.random() * 560;
    let fishY = 0;

    let dogX = Math.random() * 550;
    let dogY = -200;

    let score = 0;
    let isGoldenFish = false;
    let gameOver = false;

    function meow() {
      const sound = new Audio(
        "https://actions.google.com/sounds/v1/animals/cat_meow.ogg"
      );
      sound.play();
    }

    document.addEventListener("keydown", function(event) {
      if (gameOver) {
        return;
      }

      if (event.key === "ArrowLeft") {
        catX -= 20;
      }

      if (event.key === "ArrowRight") {
        catX += 20;
      }

      if (catX < 0) {
        catX = 0;
      }

      if (catX > 550) {
        catX = 550;
      }

      cat.style.left = catX + "px";
    });

    function gameLoop() {
      if (gameOver) {
        return;
      }

      fishY += 4;
      dogY += 3;

      fish.style.top = fishY + "px";
      fish.style.left = fishX + "px";

      dog.style.top = dogY + "px";
      dog.style.left = dogX + "px";

      checkFishCatch();
      checkDogTouch();

      if (fishY > 400) {
        resetFish();
      }

      if (dogY > 400) {
        resetDog();
      }

      requestAnimationFrame(gameLoop);
    }

    function checkFishCatch() {
      const catLeft = catX;
      const catRight = catX + 50;

      const fishLeft = fishX;
      const fishRight = fishX + 35;

      const fishIsLow = fishY > 320;
      const fishTouchesCat = fishRight > catLeft && fishLeft < catRight;

      if (fishIsLow && fishTouchesCat) {
        if (isGoldenFish) {
          score += 100;
        } else {
          score++;
        }

        scoreText.textContent = "Score: " + score;
        meow();
        resetFish();
      }
    }

    function checkDogTouch() {
      const catLeft = catX;
      const catRight = catX + 50;

      const dogLeft = dogX;
      const dogRight = dogX + 45;

      const dogIsLow = dogY > 315;
      const dogTouchesCat = dogRight > catLeft && dogLeft < catRight;

      if (dogIsLow && dogTouchesCat) {
        endGame();
      }
    }

    function resetFish() {
      fishY = 0;
      fishX = Math.random() * 560;

      // This makes about 1 out of 5 fish golden.
      isGoldenFish = Math.random() < 0.2;

      if (isGoldenFish) {
        fish.textContent = "🐠";
        fish.style.filter = "sepia(1) saturate(8) brightness(1.4)";
      } else {
        fish.textContent = "🐟";
        fish.style.filter = "none";
      }
    }

    function resetDog() {
      dogY = -200;
      dogX = Math.random() * 550;
    }

    function endGame() {
      gameOver = true;
      message.textContent = "GAME OVER!";
      restartButton.style.display = "inline-block";
    }

    function restartGame() {
      score = 0;
      scoreText.textContent = "Score: 0";

      catX = 270;
      cat.style.left = catX + "px";

      gameOver = false;
      message.textContent = "";
      restartButton.style.display = "none";

      resetFish();
      resetDog();
      gameLoop();
    }

    resetFish();
    resetDog();
    gameLoop();
  </script>

</body>
</html>
```

